/** Private native Bank/auction/supply/order acceptance after original earned profession production. */
final class MerchantTransactionRuntime {
 private static long requests=950000;
 private static void trade(ServerPlayer p,int tab,String id,int quantity){var q=CommerceService.handle(p,new com.mohymods.kingdomsmp.network.CommerceRequest(++requests,1,tab,id,quantity,com.mohymods.kingdomsmp.network.CommerceRequest.NONE));if(!q.reviewing())throw new IllegalStateException("Native trade has no review: "+q.notice());CommerceService.handle(p,new com.mohymods.kingdomsmp.network.CommerceRequest(++requests,2,tab,id,quantity,q.review()));}

 private static void hold(ServerPlayer p,ItemStack stack){p.closeContainer();int free=p.getInventory().getFreeSlot();if(free<0)throw new IllegalStateException("Private native fixture needs inventory space");if(!p.getInventory().getItem(0).isEmpty()){p.getInventory().setItem(free,p.getInventory().getItem(0));p.getInventory().setItem(0,ItemStack.EMPTY);}p.getInventory().selected=0;p.getInventory().setItem(0,stack);}
 private static void counter(ServerPlayer p,ConstructionStore.Project project){var b=BlueprintRegistry.get(project.blueprint(),1);BlacksmithRepairRuntime.near(p,project.origin().offset(b.rotate(b.home(),project.rotation())));CommerceService.openResident(p,(ReeveEntity)p.serverLevel().getEntity(project.npc()));}
 static void run(GameTestHelper h,Runnable done)throws Exception{
  var server=h.getLevel().getServer();var store=ConstructionService.store(server);var hall=ConstructionService.lodge(server);var owner=server.getPlayerList().getPlayer(hall.owner());h.assertTrue(owner!=null&&CommerceService.store(server).professions(owner.getUUID()).isActive(Profession.MERCHANT),"Original owner remains an enrolled Merchant");
  var bank=store.projects().stream().filter(p->p.blueprint().equals(RoyalBankBlueprint.ID)).findFirst().orElse(null);
  if(bank!=null){h.assertTrue(bank.phase()==ConstructionStore.Phase.COMPLETE,"Never replace an existing incomplete private fixture");load(h,bank);var savedBank=bank;h.runAfterDelay(30,()->{try{exercise(h,owner,savedBank);done.run();}catch(Exception failure){h.fail(failure.toString());}});return;}
  counter(owner,hall);var money=CommerceService.store(server);money.adminSet(UUID.randomUUID(),new UUID(0,0),owner.getUUID(),50000,"Explicit private native Bank fixture purchase supply");trade(owner,0,RoyalBankBlueprint.ID.toString(),1);bank=store.reward("market:"+RoyalBankBlueprint.ID).orElseThrow();ConstructionService.select(owner,bank.id());hold(owner,ItemStack.EMPTY);var claim=ConstructionService.review(owner,1);ConstructionService.confirm(owner,claim.nonce(),2);
  var blueprint=BlueprintRegistry.get(bank.blueprint(),1);var site=hall.origin().offset(-40,0,40);for(int x=(site.getX()-3)>>4;x<=(site.getX()+blueprint.width()+3)>>4;x++)for(int z=(site.getZ()-3)>>4;z<=(site.getZ()+blueprint.depth()+3)>>4;z++){var chunk=new BlockPos(x*16,site.getY(),z*16);h.getLevel().getChunk(x,z);ClaimRuntimeTests.ftbClaim(owner,chunk);ClaimRuntimeTests.opacClaim(h.getLevel(),owner.getUUID(),chunk);}for(var at:BlockPos.betweenClosed(site.offset(-2,-1,-3),site.offset(blueprint.width()+2,-1,blueprint.depth()+2)))h.getLevel().setBlock(at,Blocks.STONE.defaultBlockState(),18);
  owner.moveTo(site.getX()-2,site.getY()+1,site.getZ());h.getLevel().getChunkSource().move(owner);var preview=ConstructionService.preview(owner,site,Rotation.NONE);h.assertTrue(preview.denial().isBlank(),"Native Bank site passes both claims: "+preview.denial());ConstructionService.confirm(owner,ConstructionService.view(owner,1,false,"").review(),4);var start=ConstructionService.review(owner,7);ConstructionService.confirm(owner,start.nonce(),8);var post=blueprint.workPost(site,Rotation.NONE);var builder=h.getLevel().getEntity(BuilderHutSavedData.get(server).hut().orElseThrow().npcId());builder.moveTo(post.getX()+.5,post.getY(),post.getZ()+.5);build(h,owner,bank,done);
 }
 private static void load(GameTestHelper h,ConstructionStore.Project project){var box=ConstructionService.bounds(project);for(int x=((int)box.minX)>>4;x<=((int)box.maxX)>>4;x++)for(int z=((int)box.minZ)>>4;z<=((int)box.maxZ)>>4;z++)h.getLevel().getChunk(x,z);}
 private static void build(GameTestHelper h,ServerPlayer owner,ConstructionStore.Project bank,Runnable done){h.runAfterDelay(1,()->{try{var store=ConstructionService.store(owner.server);for(int i=0;i<4&&store.get(bank.id()).phase()==ConstructionStore.Phase.BUILDING;i++)ConstructionService.step(owner.server,bank.id());var current=store.get(bank.id());if(current.phase()!=ConstructionStore.Phase.COMPLETE){h.assertTrue(current.phase()==ConstructionStore.Phase.BUILDING,"Bank construction remains valid: "+current.phase());build(h,owner,current,done);return;}h.runAfterDelay(30,()->{try{exercise(h,owner,store.get(bank.id()));done.run();}catch(Exception failure){h.fail(failure.toString());}});}catch(Exception failure){h.fail(failure.toString());}});}
 private static void award(GameTestHelper h,ServerPlayer p,ConstructionStore.Project shop,String id)throws Exception{counter(p,shop);h.assertTrue(ProfessionQuestService.ready(p,id),"Only genuine settled transactions enable "+id);var q=ProfessionService.review(p,"quest:"+id);ProfessionService.confirm(p,q.nonce());boolean denied=false;try{ProfessionService.confirm(p,q.nonce());}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"A native Merchant confirmation cannot award twice");}
 private static void exercise(GameTestHelper h,ServerPlayer owner,ConstructionStore.Project bank)throws Exception{
  var store=CommerceService.store(owner.server);var shop=ConstructionService.store(owner.server).projects().stream().filter(p->p.blueprint().toString().equals(Profession.MERCHANT.buildingId())).findFirst().orElseThrow();var prior=store.professions(owner.getUUID()).track(Profession.MERCHANT);var peer=owner.server.getPlayerList().getPlayers().stream().filter(p->p!=owner).findFirst().orElseThrow();ClaimRuntimeTests.publicResidentAccess(h.getLevel(),owner.getUUID());h.assertTrue(ConstructionService.structureIntact(h.getLevel(),bank),"Real constructed Bank remains intact");
  if(prior.completedQuestIds().contains("kingdom_smp:merchant/a08")){for(var id:MerchantTransactionQuests.ids())h.assertTrue(store.merchantProof(owner.getUUID()).ready(id),"Original settled native financial evidence restores");h.assertTrue(prior.xp()==800&&prior.completedQuestIds().size()==8&&store.professions(owner.getUUID()).rank(Profession.MERCHANT,ProfessionQuestService.catalog())==ProfessionRank.JOURNEYMAN,"All8earned800XP/Journeyman and original resident restore without fabrication");CommerceService.verifyReceipt(owner);com.mojang.logging.LogUtils.getLogger().info("MERCHANT_TRANSACTION_RESTART_PASSED: all8original earned800XP/Journeyman/settled Bank-sales-order-coin-exchange evidence/native receipts/Bank and Selene survive actual JVM restart");return;}
  if(MerchantTransactionQuests.ids().stream().filter(id->!id.equals(MerchantTransactionQuests.EXCHANGE)).allMatch(prior.completedQuestIds()::contains)){finishApprentice(h,owner,peer,bank,shop);return;}
  h.assertTrue(prior.xp()==100,"Native Merchant starts only from original earned daily service");counter(owner,bank);var q=BankService.review(owner,"silver",5);BankService.confirm(owner,q.nonce());q=BankService.review(owner,"deposit",1);BankService.confirm(owner,q.nonce());h.assertTrue(store.merchantProof(owner.getUUID()).ready(MerchantTransactionQuests.DEPOSIT),"Actual native currency debit and deposit commit both directions");award(h,owner,shop,MerchantTransactionQuests.DEPOSIT);
  store.adminSet(UUID.randomUUID(),new UUID(0,0),peer.getUUID(),1000,"Explicit private counterparty funded native trades");
  // Supplied ordinary input items, never native receipt/profession/evidence injections.
  counter(owner,bank);hold(owner,new ItemStack(Items.IRON_INGOT));var sale=AuctionService.review(owner,5,"sell",1,50);AuctionService.confirm(owner,sale.nonce());h.assertTrue(!store.merchantProof(owner.getUUID()).ready(MerchantTransactionQuests.SELL),"Escrowing an item alone is not a settled sale");counter(peer,bank);var buy=AuctionService.review(peer,5,"buy:"+sale.nonce(),1,0);AuctionService.confirm(peer,buy.nonce());award(h,owner,shop,MerchantTransactionQuests.SELL);
  counter(peer,bank);hold(peer,new ItemStack(Items.COPPER_INGOT));sale=AuctionService.review(peer,5,"sell",1,50);AuctionService.confirm(peer,sale.nonce());counter(owner,bank);buy=AuctionService.review(owner,5,"buy:"+sale.nonce(),1,0);AuctionService.confirm(owner,buy.nonce());award(h,owner,shop,MerchantTransactionQuests.BUY);
  counter(owner,shop);for(var id:List.of("logs","stone","wheat")){var item=CommerceService.catalog(owner.server).supply(id).item();h.assertTrue(owner.getInventory().add(new ItemStack(item)),"Private resource inputs fit without replacing existing inventory");trade(owner,1,id,1);}award(h,owner,shop,MerchantTransactionQuests.SUPPLY);
  counter(peer,bank);hold(peer,new ItemStack(Items.GOLD_INGOT));var order=BuyOrderService.review(peer,"create",1,50);BuyOrderService.confirm(peer,order.nonce());counter(owner,bank);h.assertTrue(owner.getInventory().add(new ItemStack(Items.GOLD_INGOT)),"Private real fill input fits");var fill=BuyOrderService.review(owner,"fill:"+order.nonce(),1,0);BuyOrderService.confirm(owner,fill.nonce());award(h,owner,shop,MerchantTransactionQuests.ORDER);
  var actual=store.professions(owner.getUUID()).track(Profession.MERCHANT);h.assertTrue(actual.xp()==600&&actual.completedQuestIds().size()==6,"Actual five financial objectives earn500XP once; no missing A01/A08 or rank invented");CommerceService.verifyReceipt(owner);h.assertTrue(EconomyStore.open(owner.server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("data")).merchantProof(owner.getUUID()).equals(store.merchantProof(owner.getUUID())),"Only canonical committed financial history reopens");finishApprentice(h,owner,peer,bank,shop);com.mojang.logging.LogUtils.getLogger().info("MERCHANT_TRANSACTIONS_NATIVE_PASSED: authenticated paid Bank construction/Aldric, native50coin withdrawal/deposit/two real fixed transactions/three actual consumed Essentials sales/native funded buy-order fill and tax burn/normal Merchant review and full Apprentice800XP8proofs/replay refusal/claims/native receipts; private raw inputs and balance supply only");
 }
 private static long physical(ServerPlayer p){long total=0;for(int i=0;i<36;i++)total+=CurrencyItems.value(p.getInventory().getItem(i));return total;}
 private static void finishApprentice(GameTestHelper h,ServerPlayer owner,ServerPlayer peer,ConstructionStore.Project bank,ConstructionStore.Project shop)throws Exception{
  var store=CommerceService.store(owner.server);
  if(!store.professions(owner.getUUID()).track(Profession.MERCHANT).completedQuestIds().contains(MerchantTransactionQuests.EXCHANGE)){
   counter(owner,bank);for(var coin:List.of("copper","silver")){var withdrawal=BankService.review(owner,coin,10);BankService.confirm(owner,withdrawal.nonce());}long before=physical(owner),wallet=store.balance(owner.getUUID());
   var q=CoinExchangeService.review(owner,"exchange:copper:silver",1);var original=owner.getInventory().getItem(0).copy();owner.getInventory().setItem(0,new ItemStack(Items.DIRT));boolean denied=false;try{CoinExchangeService.confirm(owner,q.nonce());}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied&&store.merchantProof(owner.getUUID()).exchanges().isEmpty(),"Changed inventory cannot commit native physical exchange evidence");owner.getInventory().setItem(0,original);
   for(var action:List.of("exchange:copper:silver","exchange:silver:gold"))trade(owner,3,action,1);h.assertTrue(physical(owner)==before&&store.balance(owner.getUUID())==wallet,"Two actual physical exchanges preserve both face value and virtual balance");award(h,owner,shop,MerchantTransactionQuests.EXCHANGE);
  }
  // Real operator confirmation with live claims, native receipt and stable functional premises.
  owner.server.getPlayerList().op(peer.getGameProfile());var center=shop.origin().offset(7,1,6);counter(owner,shop);BlacksmithRepairRuntime.near(peer,center);BlacksmithRepairRuntime.near(owner,center);String quest="kingdom_smp:merchant/a08";String reason="Inspected genuine settled accounts coin conservation private deliveries and truthful terms";
  var inspection=ProfessionInspectionService.review(peer,owner,quest,center,reason);var changed=center.offset(0,1,0);var original=owner.serverLevel().getBlockState(changed);owner.serverLevel().setBlock(changed,Blocks.DIRT.defaultBlockState(),18);boolean refused=false;try{ProfessionInspectionService.confirm(peer,inspection);}catch(IllegalStateException expected){refused=true;}finally{owner.serverLevel().setBlock(changed,original,18);}h.assertTrue(refused,"Changed site refuses reviewed final assessment without XP");inspection=ProfessionInspectionService.review(peer,owner,quest,center,reason);ProfessionInspectionService.confirm(peer,inspection);var earned=store.professions(owner.getUUID());h.assertTrue(earned.track(Profession.MERCHANT).xp()==800&&earned.track(Profession.MERCHANT).completedQuestIds().size()==8&&earned.rank(Profession.MERCHANT,ProfessionQuestService.catalog())==ProfessionRank.JOURNEYMAN,"All8actual Merchant Apprentice objectives earn800XP/Journeyman once");CommerceService.verifyReceipt(owner);com.mojang.logging.LogUtils.getLogger().info("MERCHANT_APPRENTICE_NATIVE_PASSED: actual physical10copper-to-silver/10silver-to-gold equal-value inventory exchanges, changed-inventory refusal, canonical native receipts, all7genuine transactions/contracts plus stable OP2account inspection, changed geometry refusal, earned8proofs800XP/Journeyman and original Selene");
 }

}
